  str_help_uidrawcardcontroller_details4 = "Kamu bisa melihat pratinjau attribute dan skill Aurorian yang telah mencapai stage Ascension terakhir dengan mengetuk avatar Aurorian itu atau bilah informasi yang menampilkan namanya.",
  str_help_uidrawcardcontroller_details5 = [[
